// One item per LLR that has a linked product ticket and no "How to test" comment yet.
// A run through 'Run for One LLR' (?llr=KEY) skips the duplicate check.
const NL = String.fromCharCode(10);
let force = false;
try { const q = $('Run for One LLR').first().json.query || {}; force = !!q.llr; } catch (e) { force = false; }
function fmt(d) { try { return DateTime.fromISO(String(d).slice(0, 10)).toFormat('d LLL yyyy'); } catch (e) { return String(d || ''); } }
const issues = ($input.first().json.issues) || [];
const out = [];
for (const is of issues) {
  const f = is.fields || {};
  const comments = (f.comment && f.comment.comments) || [];
  const bodies = comments.map(function (c) { return String(c.body || ''); });
  if (!force && bodies.some(function (b) { return b.toLowerCase().indexOf('how to test') >= 0; })) { continue; }
  const link = (f.issuelinks || []).filter(function (l) { return l.type && String(l.type.name).trim() === 'Localization ticket' && l.inwardIssue; })[0];
  if (!link) { continue; }
  let release = '';
  for (const b of bodies) { const p = b.toLowerCase().indexOf('release date:'); if (p >= 0) { release = b.slice(p + 13).split(NL)[0].split('*').join('').trim(); } }
  const ready = comments.filter(function (c) { return String(c.body || '').toLowerCase().indexOf('i18n readiness check') >= 0; });
  out.push({ json: {
    llr: is.key,
    product: link.inwardIssue.key,
    llr_due: f.duedate ? fmt(f.duedate) : '',
    release_comment: release,
    readiness_date: ready.length ? fmt(ready[ready.length - 1].created) : '',
    has_qa_note: bodies.some(function (b) { return b.indexOf('First automatic QA check') >= 0; }),
    llr_comments: comments.slice(-15).map(function (c) { return { author: c.author && c.author.displayName, created: String(c.created || '').slice(0, 10), body: String(c.body || '').slice(0, 1500) }; })
  } });
}
return out;

// One request per LLR x Lokalise project: keys tagged with the product ticket key
const llrs = $('Pick LLRs Without Test Steps').all();
const projects = (($input.first().json.projects) || []).filter(function (p) { return !/demo/i.test(p.name || ''); });
const out = [];
for (let i = 0; i < llrs.length; i++) {
  const tag = llrs[i].json.product;
  for (const p of projects) {
    out.push({ json: { i: i, tag: tag, project_id: p.project_id, project_name: p.name, url: 'https://api.lokalise.com/api2/projects/' + p.project_id + '/keys?filter_tags=' + encodeURIComponent(tag) + '&filter_archived=exclude&include_translations=1&limit=100' } });
  }
  if (!projects.length) { out.push({ json: { i: i, tag: tag, project_id: '', project_name: '', url: 'https://api.lokalise.com/api2/projects?limit=1' } }); }
}
return out;

