function cut(s, n) { s = String(s || ''); return s.length > n ? s.slice(0, n) + ' ...' : s; }
const llrs = $('Pick LLRs Without Test Steps').all();
const prods = $('Get Product Ticket').all();
const epics = $('Get Epic').all();
const reqs = $('Build Lokalise Tag Requests').all();
const res = $input.all();
const out = [];
for (let i = 0; i < llrs.length; i++) {
  const L = llrs[i].json;
  const P = (prods[i] && prods[i].json) || {};
  if (P.key !== L.product) { continue; }
  const pf = P.fields || {};
  const E = (epics[i] && epics[i].json) || {};
  const epicKey = pf.parent && E.key === pf.parent.key ? E.key : '';
  const ef = epicKey ? (E.fields || {}) : {};
  const groups = {};
  for (let j = 0; j < reqs.length; j++) {
    const r = reqs[j].json;
    if (r.i !== i || !r.project_id) { continue; }
    const ks = (res[j] && res[j].json && res[j].json.keys) || [];
    for (const k of ks) {
      const kn = k.key_name || {};
      const name = typeof kn === 'string' ? kn : (kn.web || kn.other || kn.ios || kn.android || '');
      let en = '';
      for (const t of (k.translations || [])) { if (String(t.language_iso || '').toLowerCase() === 'en') { en = t.translation || ''; } }
      if (!groups[r.project_id]) { groups[r.project_id] = { project: r.project_name, keys: [] }; }
      groups[r.project_id].keys.push({ name: name, en: cut(en, 500), description: cut(k.description, 500), tags: k.tags || [] });
    }
  }
  const hash = md5(L.product);
  const links = Object.keys(groups).map(function (pid) {
    const n = groups[pid].keys.length;
    return '[' + n + ' key' + (n === 1 ? '' : 's') + ' in ' + groups[pid].project + ' – click to see|https://app.lokalise.com/project/' + pid + '/?view=multi&filter=tag_' + hash + ']';
  });
  const keysLine = links.length ? 'Keys: ' + links.join(' · ') : 'Keys: none tagged ' + L.product + ' in Lokalise';
  const status = pf.status ? pf.status.name : '';
  const live = /^(done|closed|resolved)$/i.test(status);
  const fv = pf.fixVersions || [];
  let when = '';
  if (live) {
    when = 'Live since ' + (pf.resolutiondate ? fmt(pf.resolutiondate) : 'release') + (fv[0] ? ' (' + fv[0].name + ')' : '');
  } else if (L.release_comment) {
    when = 'Release: ' + L.release_comment + ' (LLR release note)';
  } else {
    const v = fv.filter(function (x) { return x.releaseDate; })[0];
    if (v) { when = 'Release: ' + fmt(v.releaseDate) + ' (fix version ' + v.name + ')'; }
    else if (ef.duedate) { when = 'Release: ' + fmt(ef.duedate) + ' (epic ' + epicKey + ' due date)'; }
    else if (L.llr_due) { when = 'Release: ' + L.llr_due + ' (LLR due date)'; }
    else { when = 'Release: no date set yet'; }
  }
  const input = {
    llr: L.llr,
    header: { env: live ? 'production' : 'stage (not live yet)', when: when, keys_line: keysLine },
    product_ticket: { key: L.product, status: status, summary: pf.summary, labels: pf.labels || [], description: cut(pf.description, 6000),
      comments: ((pf.comment && pf.comment.comments) || []).slice(-20).map(function (c) { return { author: c.author && c.author.displayName, created: String(c.created || '').slice(0, 10), body: cut(c.body, 1500) }; }) },
    epic: epicKey ? { key: epicKey, summary: ef.summary } : null,
    llr_comments: L.llr_comments,
    readiness_check_date: L.readiness_date,
    lokalise_keys: Object.keys(groups).map(function (pid) { return groups[pid]; })
  };
