}
return out;

// Comment 1 = Claude's test steps (skipped if empty), comment 2 = how to run the readiness check (once per LLR)
const NL = String.fromCharCode(10);
const FENCE = String.fromCharCode(96, 96, 96);
const meta = $('Build Prompts').all();
const llm = $input.all();
const out = [];
for (let i = 0; i < meta.length; i++) {
  const m = meta[i].json;
  const j = (llm[i] && llm[i].json) || {};
  let t = j.merged_response || '';
  if (!t && Array.isArray(j.content)) { t = j.content.filter(function (c) { return c.type === 'text'; }).map(function (c) { return c.text; }).join(''); }
  t = String(t || '').split(FENCE + 'jira').join('').split(FENCE).join('').trim();
  const p = t.indexOf('*How to test');
  if (p < 0) { continue; }
  out.push({ json: { llr: m.llr, kind: 'test_steps', body: t.slice(p) } });
  if (!m.has_qa_note) {
    const lines = [
      '*First automatic QA check — i18n readiness*',
      'To run it, open Claude and:',
      '# Run the skill *i18n-readiness*',
      '# Tap *Start right away*',
      '# Select *Jira ticket*',
      '# Enter *' + m.llr + '*',
      '',
      'The skill finds the linked product ticket (' + m.product + ') and its Lokalise keys by itself. It posts the Excel workbook link here when it is done.'
    ];
    if (m.readiness_date) { lines.push('Already run once on ' + m.readiness_date + ', see the readiness comment above.'); }
    out.push({ json: { llr: m.llr, kind: 'qa_note', body: lines.join(NL) } });
  }
}
return out;

